  'Alternative': 'Alternativa',
  'Véhicule normalement sale (poussière, pluie, pollen)': 'Vehículo normalmente sucio (polvo, lluvia, polen)',
  'Parfait': 'Perfecto',
  'Boue, sable, sel de route': 'Barro, arena, sal de carretera',
